import type { Cuestionario, PreguntaCuestionario } from "./cuestionarios";
import { cuestionariosTematicosOS10 } from "./cuestionarios-os10-tematicos";

function alt(
  id: string,
  pregunta: string,
  correcta: string,
  distractores: [string, string, string],
  explicacion?: string
): PreguntaCuestionario {
  return {
    id,
    tipo: "alternativa",
    texto: pregunta,
    opciones: [correcta, ...distractores],
    respuestaCorrecta: correcta,
    explicacion: explicacion || correcta,
  };
}

